+// Encode encodes the LaxPolygon.
+func (p *LaxPolygon) Encode(w io.Writer) error {
+	e := &encoder{w: w}
+	p.encode(e)
+	return e.err
+}
+
+func (p *LaxPolygon) encode(e *encoder) {
+	e.writeInt8(encodingVersion)
+	e.writeUint32(uint32(p.numLoops))
+	for i := 0; i < p.numLoops; i++ {
+		e.writeUint32(uint32(p.numLoopVertices(i)))
+	}
+	for _, pt := range p.vertices {
+		e.writeFloat64(pt.X)
+		e.writeFloat64(pt.Y)
+		e.writeFloat64(pt.Z)
+	}
+}
+
+// Decode decodes the LaxPolygon.
+func (p *LaxPolygon) Decode(r io.Reader) error {
+	d := &decoder{r: asByteReader(r)}
+	p.decode(d)
+	return d.err
+}
+
+func (p *LaxPolygon) decode(d *decoder) {
+	version := d.readInt8()
+	if d.err != nil {
+		return
+	}
+	if version != encodingVersion {
+		d.err = fmt.Errorf("cannot decode version %d; my version: %d", version, encodingVersion)
+		return
+	}
+	nloops := d.readUint32()
+	if d.err != nil {
+		return
+	}
+	if nloops > maxEncodedLoops {
+		d.err = fmt.Errorf("too many loops (%d; max is %d)", nloops, maxEncodedLoops)
+		return
+	}
+	if nloops == 0 {
+		*p = *LaxPolygonFromPoints(nil)
+		return
+	}
+	loopSizes := make([]int, nloops)
+	totalVertices := 0
+	for i := range loopSizes {
+		sz := d.readUint32()
+		if d.err != nil {
+			return
+		}
+		if sz > maxEncodedVertices {
+			d.err = fmt.Errorf("too many loop vertices (%d; max is %d)", sz, maxEncodedVertices)
+			return
+		}
+		totalVertices += int(sz)
+		if totalVertices > maxEncodedVertices {
+			d.err = fmt.Errorf("total vertices exceed max (%d; max is %d)", totalVertices, maxEncodedVertices)
+			return
+		}
+		loopSizes[i] = int(sz)
+	}
+	loops := make([][]Point, nloops)
+	for i, sz := range loopSizes {
+		loops[i] = make([]Point, sz)
+		for j := range loops[i] {
+			loops[i][j].X = d.readFloat64()
+			loops[i][j].Y = d.readFloat64()
+			loops[i][j].Z = d.readFloat64()
+		}
+	}
+	if d.err != nil {
+		return
+	}
+	*p = *LaxPolygonFromPoints(loops)
+}
